void tim2_init(void) {
    TIM2->PSC = 83;
    TIM2->EGR = TIM_EGR_UG;      // loads PSC, but also sets UIF
    TIM2->SR = ~TIM_SR_UIF;      // clear it before enabling the IRQ
    TIM2->DIER |= TIM_DIER_UIE;
    NVIC_ClearPendingIRQ(TIM2_IRQn);
    NVIC_EnableIRQ(TIM2_IRQn);
}
